import React from 'react';
import { ORDER_STATUS_THEME } from '../../utils/cashier';
import { ORDER_STATUS_LABELS } from '../../utils/roles';

/** Badge de estado del pedido, con tonos alineados a la paleta corporativa. */
const StatusBadge = ({ status }) => {
  const tone = ORDER_STATUS_THEME[status] || 'info';
  return (
    <span className={`cashier-badge cashier-badge--${tone}`}>
      {ORDER_STATUS_LABELS[status] || status}
    </span>
  );
};

export default StatusBadge;
